output_text:
[
  {
    "id": "use_entry_cart",
    "text": "Customers are obliged to take the cart from the entry cart station before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "no_hand_item_pickup",
    "text": "Customers are prohibited from picking up items by hand rather than into a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_item_pickup"
    }
  },
  {
    "id": "return_cart_after_items",
    "text": "After collecting any item with a cart, customers are obliged to return the cart to the northwest cart-return point.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "item_collected_with_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "pushing_cart"
        },
        "return_cart_northwest": {
          "pre": {
            "and": [
              "pushing_cart",
              "cart_return_point",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected_with_cart",
      "discharge": "return_cart_northwest"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from leaving the supermarket while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "only_leave_cart_at_return",
    "text": "Customers are prohibited from leaving a cart anywhere except the northwest cart-return cell.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "abandon_cart_away_from_return": {
          "pre": {
            "and": [
              "pushing_cart",
              "LEAVE_CART",
              {
                "not": "cart_return_point"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_away_from_return"
    }
  },
  {
    "id": "cart_west_wall_no_east_turn",
    "text": "While pushing a cart on the west-wall return corridor, customers are prohibited from turning east into the store aisles.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "west_wall_return_corridor": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "cart_in_return_corridor": {
          "and": [
            "pushing_cart",
            "west_wall_return_corridor"
          ]
        }
      },
      "events": {
        "east_turn_with_cart_from_west_wall": {
          "pre": {
            "and": [
              "cart_in_return_corridor",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_turn_with_cart_from_west_wall"
    }
  },
  {
    "id": "cart_middle_station_no_south",
    "text": "When pushing a cart at the middle lower shelf station, customers are prohibited from moving south into the bottom aisle.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "middle_lower_station": "at(2,4)",
        "cart_at_middle_lower_station": {
          "and": [
            "pushing_cart",
            "middle_lower_station"
          ]
        }
      },
      "events": {
        "south_from_middle_with_cart": {
          "pre": {
            "and": [
              "cart_at_middle_lower_station",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "south_from_middle_with_cart"
    }
  },
  {
    "id": "cart_east_station_no_direct_exit",
    "text": "When pushing a cart at the eastern shelf station, customers are prohibited from continuing east or south toward the exit side.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "east_shelf_station": "at(6,4)",
        "cart_at_east_shelf_station": {
          "and": [
            "pushing_cart",
            "east_shelf_station"
          ]
        },
        "direct_exit_direction": {
          "or": [
            "E",
            "S"
          ]
        }
      },
      "events": {
        "direct_exit_move_with_cart_from_east_station": {
          "pre": {
            "and": [
              "cart_at_east_shelf_station",
              "direct_exit_direction"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "direct_exit_move_with_cart_from_east_station"
    }
  }
]
